INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(118491, 'ruRU', '', 'Иногда тебе нужно, чтобы враг оставался на месте, чтобы ты мог сократить расстояние до него... или совершить поспешное отступление.', 24330),
(118492, 'ruRU', '', 'Используй Гнев солнца на тренировочном манекене, пока у тебя не будет достаточно Астральной силы для Звёздного всплеска.', 24330),
(118493, 'ruRU', '', 'Одна из твоих самых мощных атак, Звёздный всплеск, обрушивает на цель всплеск звёздной энергии.', 24330),
(118494, 'ruRU', '', 'Используй Гнев солнца на тренировочном манекене.', 24330),
(118495, 'ruRU', '', 'Как только враг начинает получать урон от твоих других атак, время высвободить Гнев солнца.', 24330),
(118496, 'ruRU', '', 'Обе эти атаки наносят урон со временем. Применив их, тебе не нужно применять их снова, пока эффект на цели не истечёт.', 24330),
(118497, 'ruRU', '', 'Используй Лунный огонь и Солнечный огонь на тренировочном манекене.', 24330),
(118498, 'ruRU', '', 'Ты направляешь саму силу ночи и дня против своих врагов. Лунный огонь и Солнечный огонь воплощают эту силу.', 24330),
(118499, 'ruRU', '', 'Используй Облик лунного совуха и прими форму дикозверя.', 24330),
(118500, 'ruRU', '', 'Будучи друидом равновесия, солнце, луна и звёзды — твои союзники, позволяющие обрушивать эти первородные силы на твоих врагов.', 24330),
(118501, 'ruRU', '', 'Опутывающие корни заставят растительные корни вырваться из земли и удержать цель на месте на короткое время.', 24330),
(118502, 'ruRU', '', 'Лунный удар наносит урон прямо твоей цели, но также наносит урон находящимся рядом врагам.', 24330),
(118503, 'ruRU', '', 'Небесное согласование заставляет небесные тела выровняться, увеличивая урон твоих солнечных и лунных заклинаний на короткое время.', 24330),
(118504, 'ruRU', '', 'Звёздный всплеск требует Астральной силы, так что используй Гнев солнца, чтобы накопить запасы.', 24330),
(118505, 'ruRU', '', 'Гнев солнца — способность дальнего действия, наносящая урон и накапливающая Астральную силу — ресурс, питающий более мощные атаки.', 24330),
(118506, 'ruRU', '', 'Эти атаки наносят урон со временем, и любая из них отлично подходит для начала боя.', 24330),
(118507, 'ruRU', '', 'Ты можешь принять Облик лунного совуха, что увеличивает и твой урон, и защиту.', 24330),
(118508, 'ruRU', '', 'У тебя максимум Астральной силы. Используй Звёздный всплеск!', 24330),
(118509, 'ruRU', '', 'Используй Лунный удар!', 24330),
(118510, 'ruRU', '', 'Используй Опутывающие корни!', 24330),
(118511, 'ruRU', '', 'Попробуй обездвижить цель, прежде чем она доберётся до тебя! Давай попробуем снова!', 24330),
(118512, 'ruRU', '', 'Попробуй использовать Опутывающие корни, чтобы обездвижить свою цель!', 24330),
(118513, 'ruRU', '', 'Используй Звёздный всплеск!', 24330),
(118514, 'ruRU', '', 'Звёздный всплеск доступен! Используй его сейчас!', 24330),
(118521, 'ruRU', '', 'DELETE', 24330),
(118522, 'ruRU', '', '$n, выйди вперёд.', 24330),
(118523, 'ruRU', '', 'Обернись и встань лицом к своим собратьям, $p, чтобы они могли засвидетельствовать твою беспощадность и хитрость.', 24330),
(118524, 'ruRU', '', 'Перед вами стоит величайший защитник Орды, герой бесчисленных побед над нашим неумолимым врагом.', 24330),
(118525, 'ruRU', '', 'Древнее оружие, которым он владеет, внушает страх в сердца тех, кто угрожает нашему образу жизни.', 24330),
(118526, 'ruRU', '', 'Так присоединяйтесь ко мне, герои, в чествовании $p, проклятия Альянса!', 24330),
(118527, 'ruRU', '', 'За Орду!', 24330),
(118529, 'ruRU', '', 'Привет, мой дорогой. Всегда приятно тебя видеть.\n\nЧем я могу помочь?', 24330),
(118569, 'ruRU', '', 'Здесь, так далеко от Ночного Колодца, нам приходится довольствоваться любым источником магии, что мы можем найти.', 24330),
(118570, 'ruRU', '', 'Похоже, у Талисры и у меня возникла та же мысль — старые питающие лей-линии могут удержать нас в живых, хоть и едва.', 24330),
(118571, 'ruRU', '', 'Нам просто нужно разбудить их.', 24330),
(118575, 'ruRU', '', 'Вот... ты что-то нашёл, не так ли?', 24330),
(118576, 'ruRU', '', 'Что-то, что дало тебе покой...', 24330),
(118583, 'ruRU', '', 'Покой, в котором мы сами так отчаянно нуждаемся.', 24330),
(118584, 'ruRU', '', 'Ты жив, Борос, и это главное. Идём, вернёмся в часовню Последней Надежды.', 24330),
(118597, 'ruRU', '', 'Приятно видеть тебя снова, $n.', 24330);
